head.script:
// =============================================================================
/**
 * 로그인 세션 점검 등 세션 제어 관련 함수를 작성한다.
 *
 * @author Inswave Systems
 * @class session
 * @namespace $c.session
 */
// =============================================================================

// 세션 무효 시 이동할 로그인 페이지 URL (필요 시 프로젝트에 맞게 변경)
scwin.LOGIN_URL = "/index.html";

scwin.onpageload = function () {

};

/**
 * @method
 * @name sessionCheck
 * @description 로그인 세션 ID 가 없으면(미로그인/만료) 안내 메시지 후 로그인 페이지로 이동시킨다.
 * @param {String} sessionId 검사할 세션/로그인 ID. 생략 시 전역 변수 js_id 를 사용한다.
 * @returns {void}
 * @hidden N
 * @exception
 * @example
$c.session.sessionCheck();                 // 전역 js_id 기준 검사
$c.session.sessionCheck(scwin.loginId);    // 명시적 ID 기준 검사
 */
scwin.sessionCheck = function (sessionId) {
    const id = (typeof sessionId !== "undefined")
        ? sessionId
        : ((typeof js_id !== "undefined") ? js_id : null);

    if ($c.util.isEmpty(id)) {
        alert("세션이 만료되었습니다. 로그인 페이지로 이동합니다.");
        top.document.location.href = scwin.LOGIN_URL;
    }
};
